function buildToyotaDetail(subject: string, language: string): string {
  const suffix = toyotaDetailTemplates[language]?.suffix || toyotaDetailTemplates.en.suffix;
  return language === 'zh' ? `${subject}，${suffix}` : `${subject} ${suffix}`;
}

export function getTranslatedToyotaSparePartDetails(name: string, language: string = 'en'): string {
  const detailKind = toyotaPartDetailKinds[name];
  if (detailKind) {
    const subject = toyotaDetailSubjects[detailKind][language] || toyotaDetailSubjects[detailKind].en;
    return buildToyotaDetail(subject, language);
  }

  return (toyotaPartDetailsTranslations.default as Record<string, string>)[language]
    || toyotaPartDetailsTranslations.default.en;
}
